<?php
require_once __DIR__ . '/../connection.php';
require_once __DIR__ . '/../classes/CollectionSchedule.php';

$entity = $_GET['entity'] ?? '';
$labels = [
    'violators' => 'Violator', 'collectors' => 'Collector', 'residents' => 'Resident',
    'complaints' => 'Complaint', 'violations' => 'Violation',
    'notifications' => 'Notification', 'activity_logs' => 'Activity Log'
];
if (!isset($labels[$entity])) { header('Location: ../index.php'); exit; }
$users = $pdo->query('SELECT User_id, Fullname FROM users ORDER BY Fullname')->fetchAll();
$zones = $pdo->query('SELECT Zone_ID, Zone_Name, Barangay FROM zones ORDER BY Zone_Name')->fetchAll();
$violators = $pdo->query('SELECT ViolatorID, FullName FROM violators ORDER BY FullName')->fetchAll();
$residents = $pdo->query('SELECT ResidentID, HomeAddress FROM residents ORDER BY ResidentID')->fetchAll();
$complaints = $pdo->query('SELECT ComplaintID, Description FROM complaints ORDER BY ComplaintID')->fetchAll();
?>
<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Add <?= htmlspecialchars($labels[$entity]) ?></title><link rel="stylesheet" href="../style.css?v=11"></head>
<body><main class="container entity-form-page"><p class="eyebrow">ERD TABLE RECORD</p><h1>Add <?= htmlspecialchars($labels[$entity]) ?></h1><p class="form-intro">Add a record to the <?= htmlspecialchars(ucwords(str_replace('_', ' ', $entity))) ?> table.</p>
<form class="form-container entity-form" action="../backend/collection_code.php" method="post" enctype="multipart/form-data"><input type="hidden" name="entity" value="<?= htmlspecialchars($entity) ?>">
<?php if ($entity === 'violators'): ?><label>Full Name</label><input name="full_name" required><label>Address</label><input name="address" required><label>Contact Number</label><input name="contact_number"><label>Violation Count</label><input type="number" name="violation_count" min="0" value="0" required>
<?php elseif ($entity === 'collectors'): ?><label>Zone</label><select name="zone_id" required><?php foreach ($zones as $zone): ?><option value="<?= $zone['Zone_ID'] ?>"><?= htmlspecialchars($zone['Zone_Name'] . ' - ' . $zone['Barangay']) ?></option><?php endforeach; ?></select><label>User</label><select name="user_id" required><?php foreach ($users as $user): ?><option value="<?= $user['User_id'] ?>"><?= htmlspecialchars($user['Fullname']) ?></option><?php endforeach; ?></select><label>Vehicle Plate</label><input name="vehicle_plate" required>
<?php elseif ($entity === 'residents'): ?><label>User</label><select name="user_id" required><?php foreach ($users as $user): ?><option value="<?= $user['User_id'] ?>"><?= htmlspecialchars($user['Fullname']) ?></option><?php endforeach; ?></select><label>Zone</label><select name="zone_id" required><?php foreach ($zones as $zone): ?><option value="<?= $zone['Zone_ID'] ?>"><?= htmlspecialchars($zone['Zone_Name'] . ' - ' . $zone['Barangay']) ?></option><?php endforeach; ?></select><label>Household No</label><input type="number" name="household_no" required><label>Home Address</label><input name="home_address" required>
<?php elseif ($entity === 'complaints'): ?><label>Resident</label><select name="resident_id" required><?php foreach ($residents as $resident): ?><option value="<?= $resident['ResidentID'] ?>">#<?= $resident['ResidentID'] ?> - <?= htmlspecialchars($resident['HomeAddress']) ?></option><?php endforeach; ?></select><label>Location</label><input name="location" required><label>Description</label><input name="description" required><label>Date Reported</label><input type="date" name="date_reported" required><label>Photo Evidence</label><input type="file" name="photo_evidence" accept="image/jpeg,image/png,image/webp" required><label>Status</label><select name="status"><option>Pending</option><option>Under Review</option><option>Resolved</option></select>
<?php elseif ($entity === 'violations'): ?><label>Complaint</label><select name="complaint_id" required><?php foreach ($complaints as $complaint): ?><option value="<?= $complaint['ComplaintID'] ?>">#<?= $complaint['ComplaintID'] ?> - <?= htmlspecialchars($complaint['Description']) ?></option><?php endforeach; ?></select><label>Violator</label><select name="violator_id" required><?php foreach ($violators as $violator): ?><option value="<?= $violator['ViolatorID'] ?>">#<?= $violator['ViolatorID'] ?> - <?= htmlspecialchars($violator['FullName']) ?></option><?php endforeach; ?></select><label>Fine Amount</label><input type="number" name="fine_amount" min="0" required><label>Date Issued</label><input type="date" name="date_issued" required><label>Status</label><select name="status"><option>Pending</option><option>Unpaid</option><option>Paid</option></select>
<?php elseif ($entity === 'notifications'): ?><label>User</label><select name="user_id" required><?php foreach ($users as $user): ?><option value="<?= $user['User_id'] ?>"><?= htmlspecialchars($user['Fullname']) ?></option><?php endforeach; ?></select><label>Message</label><input name="message" required><label>Date Sent</label><input type="date" name="date_sent" required><label>Status</label><select name="status"><option>Unread</option><option>Read</option></select>
<?php else: ?><label>User</label><select name="user_id" required><?php foreach ($users as $user): ?><option value="<?= $user['User_id'] ?>"><?= htmlspecialchars($user['Fullname']) ?></option><?php endforeach; ?></select><label>Action Taken</label><input name="action_taken" required><label>Timestamp</label><input type="time" name="timestamp" required><?php endif; ?><div class="form-actions"><button type="submit" name="add_entity_record">Save Record</button><a href="../index.php">Cancel</a></div></form></main></body></html>
